export function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return null
  let p = 0
  const peek = () => toks[p]
  const isOp = (v) => p < toks.length && toks[p].t === 'op' && toks[p].v === v
  const bad = new Error('syntax')

  function comparison() {
    let l = additive()
    while (p < toks.length && toks[p].t === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: additive() }
    }
    return l
  }
  function additive() {
    let l = term()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: term() }
    }
    return l
  }
  function term() {
    let l = power()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: power() }
    }
    return l
  }
  function power() {
    const l = unary()
    if (isOp('^')) { p++; return { k: 'bin', op: '^', l, r: power() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { k: 'un', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    const t = peek()
    if (!t) throw bad
    if (t.t === 'num') { p++; return { k: 'num', v: t.v } }
    if (t.t === 'op' && t.v === '(') {
      p++
      const e = comparison()
      if (!isOp(')')) throw bad
      p++
      return { k: 'paren', e }
    }
    if (t.t === 'word') {
      p++
      if (isOp('(')) {
        p++
        const args = []
        if (isOp(')')) { p++ } else {
          for (;;) {
            args.push(comparison())
            if (isOp(',')) { p++; continue }
            if (isOp(')')) { p++; break }
            throw bad
          }
        }
        return { k: 'call', name: t.v.toUpperCase(), args }
      }
      const up = t.v.toUpperCase()
      if (up === 'TRUE') return { k: 'bool', v: true }
      if (up === 'FALSE') return { k: 'bool', v: false }
