export function rangeCells(a, b) {
  const x = validAddr(a), y = validAddr(b)
  if (!x || !y) return null
  const cx = /^[A-Z]+/.exec(x)[0], cy = /^[A-Z]+/.exec(y)[0]
  const ci = (c) => (c.length === 1 ? c.charCodeAt(0) - 64 : (c.charCodeAt(0) - 64) * 26 + c.charCodeAt(1) - 64)
  const cn = (n) => (n <= 26 ? String.fromCharCode(64 + n) : String.fromCharCode(64 + Math.floor((n - 1) / 26)) + String.fromCharCode(65 + ((n - 1) % 26)))
  const c1 = Math.min(ci(cx), ci(cy)), c2 = Math.max(ci(cx), ci(cy))
  const r1 = Math.min(Number(x.slice(cx.length)), Number(y.slice(cy.length)))
  const r2 = Math.max(Number(x.slice(cx.length)), Number(y.slice(cy.length)))
  const res = []
  for (let c = c1; c <= c2; c++) for (let r = r1; r <= r2; r++) res.push(cn(c) + r)
  return res
}

export function collectDeps(ast) {
  const set = new Set()
  const walk = (n) => {
    switch (n.k) {
      case 'ref': { const a = validAddr(n.w); if (a) set.add(a); break }
      case 'range': { const r = rangeCells(n.a, n.b); if (r) r.forEach((x) => set.add(x)); break }
      case 'bin': walk(n.l); walk(n.r); break
      case 'un': case 'paren': walk(n.e); break
      case 'call': n.args.forEach(walk); break
    }
  }
  walk(ast)
  return [...set]
}
