import { parseFormula, validAddr, rangeCells } from './formula.js'

const ERRORS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const err = (e) => ({ k: 'err', e })
const num = (v) => ({ k: 'num', v })
const isErr = (x) => x.k === 'err'
const ZERO = num(0)

export function formatValue(v) {
  switch (v.k) {
    case 'num': return String(Number(v.v.toPrecision(10)))
    case 'err': return v.e
    case 'bool': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

function literal(c) {
  if (c === '') return ZERO
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(c)) return num(parseFloat(c))
  if (ERRORS.includes(c)) return err(c)
  return { k: 'text', v: c }
}

function toNum(x) {
  if (x.k === 'num') return x
  if (x.k === 'bool') return num(x.v ? 1 : 0)
  return err('#VALUE!')
}
const fin = (v) => (Number.isFinite(v) ? num(v) : err('#DIV/0!'))
const rank = { num: 0, text: 1, bool: 2 }

export function evaluateSheet(cells) {
  const memo = new Map()
  const active = new Set()
  const asts = new Map()

  function cell(addr) {
    if (!cells.has(addr)) return ZERO
    if (memo.has(addr)) return memo.get(addr)
    if (active.has(addr)) return err('#CYCLE!')
    active.add(addr)
    const c = cells.get(addr)
    let r
    if (c[0] === '=') {
      const ast = parseFormula(c.slice(1))
      r = ast ? ev(ast) : err('#ERR!')
    } else r = literal(c)
    active.delete(addr)
    memo.set(addr, r)
    return r
  }

  function args(list) {
    const out = []
    for (const a of list) {
      if (a.k === 'range') {
        const r = rangeCells(a.a, a.b)
        if (!r) out.push(err('#REF!'))
        else for (const x of r) out.push(cell(x))
      } else out.push(ev(a))
    }
    return out
  }

  function ev(n) {
    switch (n.k) {
      case 'num': return num(n.v)
      case 'bool': return { k: 'bool', v: n.v }
      case 'paren': return ev(n.e)
      case 'range': return err('#ERR!')
      case 'ref': { const a = validAddr(n.w); return a ? cell(a) : err('#REF!') }
      case 'un': {
        const x = ev(n.e)
        if (isErr(x)) return x
        const y = toNum(x)
        if (isErr(y)) return y
        return n.op === '-' ? num(-y.v) : y
      }
      case 'bin': {
        const l = ev(n.l), r = ev(n.r)
        if (isErr(l)) return l
        if (isErr(r)) return r
        if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
          let c
          if (l.k !== r.k) c = rank[l.k] - rank[r.k]
          else if (l.k === 'text') c = l.v === r.v ? 0 : cpCompare(l.v, r.v)
          else c = Number(l.v) - Number(r.v)
          if (l.k === 'num') c = l.v < r.v ? -1 : l.v > r.v ? 1 : 0
          const res = { '=': c === 0, '<>': c !== 0, '<': c < 0, '<=': c <= 0, '>': c > 0, '>=': c >= 0 }[n.op]
          return { k: 'bool', v: res }
        }
        const a = toNum(l), b = toNum(r)
        if (isErr(a)) return a
        if (isErr(b)) return b
        switch (n.op) {
          case '+': return fin(a.v + b.v)
          case '-': return fin(a.v - b.v)
          case '*': return fin(a.v * b.v)
          case '/': return b.v === 0 ? err('#DIV/0!') : fin(a.v / b.v)
          default: return fin(Math.pow(a.v, b.v))
        }
      }
      case 'call': return call(n)
    }
  }

  function call(n) {
    const f = n.name
    const variadic = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG']
    if (variadic.includes(f)) {
      if (n.args.length < 1) return err('#ERR!')
      const vs = args(n.args)
      const e = vs.find(isErr)
      if (e) return e
      if (f === 'COUNT') return num(vs.filter((v) => v.k === 'num').length)
      const ns = []
      for (const v of vs) {
        const x = toNum(v)
        if (isErr(x)) return x
        ns.push(x.v)
      }
      if (f === 'SUM') return fin(ns.reduce((a, b) => a + b, 0))
      if (f === 'MIN') return num(Math.min(...ns))
      if (f === 'MAX') return num(Math.max(...ns))
      return fin(ns.reduce((a, b) => a + b, 0) / ns.length)
    }
    if (f === 'ABS') {
      if (n.args.length !== 1) return err('#ERR!')
      const x = ev(n.args[0])
      if (isErr(x)) return x
      const y = toNum(x)
      return isErr(y) ? y : num(Math.abs(y.v))
    }
    if (f === 'IF') {
      if (n.args.length !== 3) return err('#ERR!')
      const c = ev(n.args[0])
      if (isErr(c)) return c
      let t
      if (c.k === 'bool') t = c.v
      else if (c.k === 'num') t = c.v !== 0
      else return err('#VALUE!')
      return ev(n.args[t ? 1 : 2])
    }
    return err('#NAME?')
  }

  const res = new Map()
  for (const k of cells.keys()) res.set(k, cell(k))
  return res
}

function cpCompare(a, b) {
  const x = Array.from(a), y = Array.from(b)
  for (let i = 0; i < Math.min(x.length, y.length); i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}
